1	import { execFile } from "node:child_process";
2	import { promisify } from "node:util";
3	import { db } from "./db";
4	import { ovh, ovhApi, ovhConfigured } from "./ovh";
5	import { hetznerApi, hetznerConfigured } from "./hetzner";
6	import { SANDBOX, sandboxIp, sandboxMac } from "./sandbox";
7	import { getSettingInt } from "./settings";
8	import type { NodeProvider } from "@prisma/client";
9	
10	const execFileP = promisify(execFile);
11	
12	/**
13	 * Is this address already the target of a live DNAT rule on this host? Some
14	 * infrastructure (the shared-hosting node, VM 200) reaches its dedicated IP
15	 * entirely through a whole-IP DNAT rule to an internal address — it has no OVH
16	 * Virtual MAC at all, so the MAC-based check above cannot see it. A real
17	 * incident: this exact IP was one query away from being handed to a game
18	 * server because "no Virtual MAC bound" was mistaken for "free" — it was
19	 * actively carrying production hosting traffic via `iptables -t nat`. Treat
20	 * any address with a live DNAT target as claimed, unconditionally.
21	 */
22	async function hasLiveDnatRule(address: string): Promise<boolean> {
23	  try {
24	    const { stdout } = await execFileP("iptables", ["-t", "nat", "-S", "PREROUTING"]);
25	    return stdout.split("\n").some((line) => line.includes(`-d ${address}/32`) && line.includes("-j DNAT"));
26	  } catch {
27	    // iptables unreadable (permissions, not present, sandboxed test env) — fail
28	    // closed is wrong here (it would make every sync a no-op); fail to "not
29	    // claimed by this specific check" and rely on the Virtual MAC check plus
30	    // the existing DB row remaining authoritative for anything already tracked.
31	    return false;
32	  }
33	}
34	
35	/**
36	 * What OVH actually bills per additional/failover IPv4 in the pool, in cents.
37	 * Single source of truth for both the IP-pool page's "OVH cost" stat and the
38	 * admin Accounting dashboard's auto-pulled infrastructure expense line — before
39	 * this it existed only as a copy of the same number hardcoded on the IP page.
40	 * NOTE: OVH-specific — a Hetzner pool's real cost isn't folded into this
41	 * figure yet (no Hetzner IPs exist in the pool at the time this was written).
42	 */
43	export const OVH_IP_UNIT_COST_CENTS = 239;
44	
45	/**
46	 * Fallback monthly price for a dedicated IPv4. Defaults to 0 — a dedicated IP is
47	 * INCLUDED on every plan (its cost is folded into plan pricing, as the marketing
48	 * pages state). The admin `dedicated_ip_price_cents` setting is the source of
49	 * truth; use `dedicatedIpMonthlyCents()` in billing paths, not this constant.
50	 */
51	export const DEDICATED_IP_PRICE_CENTS = Number(process.env.DEDICATED_IP_PRICE_CENTS ?? 0);
52	
53	/**
54	 * The monthly dedicated-IP surcharge actually charged, from the admin setting
55	 * (`dedicated_ip_price_cents`, default 0 = included). Single source of truth for
56	 * every order/renewal/display path so they can never disagree.
57	 *
58	 * NORMALISED to a non-negative whole number of cents, exactly as
59	 * `extraDiskPerGbCents` (lib/disk-expand.ts) already does for the other
60	 * admin-priced add-on. `getSettingInt` is a raw `Number()` of whatever string sits
61	 * in the `Setting` row, so it happily returns 2.5 or -500. This value is multiplied
62	 * by the term length straight into `chargeCents` (lib/order.ts orderQuote) and into
63	 * `renewalCharge`, and from there into `debitWallet`, `unit_amount` and an Invoice
64	 * row — every one of which is integer cents. A fractional setting produced a
65	 * fractional charge that failed at Stripe or Prisma AFTER the customer had agreed
66	 * to it; a negative one silently discounted the plan.
67	 */
68	export async function dedicatedIpMonthlyCents(): Promise<number> {
