125	async function syncOvhPool(node: NodeRow): Promise<{ imported: number; total: number }> {
126	  if (!ovhConfigured()) return { imported: 0, total: 0 };
127	  const SERVER = node.providerServerId!;
128	  const primary = node.publicIp;
129	  const blocks: string[] = await ovhApi.ips();
130	  let imported = 0;
131	  for (const block of blocks) {
132	    if (block.includes(":")) continue; // IPv6 handled separately
133	    let info: any;
134	    try {
135	      info = await ovhApi.ipInfo(block);
136	    } catch {
137	      continue;
138	    }
139	    if (info?.routedTo?.serviceName !== SERVER) continue;
140	    if (info?.type !== "failover" && info?.type !== "additional") continue; // exclude the primary "dedicated" host IP
141	    // A /32 block is a single usable IP == the block minus the mask.
142	    const address = block.split("/")[0];
143	    if (address === primary) continue;
144	    const existing = await db.dedicatedIp.findUnique({ where: { address } });
145	    if (!existing) {
146	      // An IP that already has a Virtual MAC bound to it on OVH's side is already
147	      // in active use by SOME VM — possibly one this app never created a Server
148	      // row for (e.g. internal infrastructure provisioned directly via the OVH
149	      // API, like the cold-email relay). A genuinely free IP has no bound MAC
150	      // yet. Importing it as FREE anyway let a real customer server collide with
151	      // an unrelated VM's network identity — never assign an IP that's already
152	      // claimed at the network layer, regardless of whether our DB knows about it.
153	      if (await findVirtualMacForIp(SERVER, address)) continue;
154	      if (await hasLiveDnatRule(address)) continue;
155	      // Every IP this function imports is, by construction, a spare address
156	      // OVH says is routed to us and not yet claimed at the network layer — the
157	      // pool customer orders draw from. Internal-use IPs (the cold-email relay,
158	      // an owner-operated site, the shared-hosting node) are rare, hand-provisioned
159	      // one-offs marked INTERNAL by an admin after the fact; this sync has no way
160	      // to tell them apart from a genuinely free customer IP and must not try —
161	      // it always imports as CUSTOMER (the schema default, stated here for clarity).
162	      await db.dedicatedIp.create({ data: { address, ovhBlock: block, nodeId: node.id, status: "FREE", purpose: "CUSTOMER" } });
163	      imported++;
164	    }
165	  }
166	  const total = await db.dedicatedIp.count({ where: { nodeId: node.id } });
167	  return { imported, total };
168	}
