170	/**
171	 * Hetzner side of the sync. Hetzner's `/ip` listing already returns exactly
172	 * the single additional IPs on the account (no failover/additional type
173	 * distinction to filter like OVH's `/ip` does) — every entry not equal to the
174	 * node's own main `publicIp` is poolable.
175	 */
176	async function syncHetznerPool(node: NodeRow): Promise<{ imported: number; total: number }> {
177	  if (!hetznerConfigured()) return { imported: 0, total: 0 };
178	  let imported = 0;
179	  const ips: Array<{ ip: string }> = await hetznerApi.ips().catch(() => []);
180	  for (const entry of ips) {
181	    const address = entry.ip;
182	    if (!address || address === node.publicIp) continue;
183	    const existing = await db.dedicatedIp.findUnique({ where: { address } });
184	    if (existing) continue;
185	    if (await hasLiveDnatRule(address)) continue;
186	    await db.dedicatedIp.create({
187	      data: { address, ovhBlock: "", nodeId: node.id, status: "FREE", purpose: "CUSTOMER" },
188	    });
189	    imported++;
190	  }
191	  const total = await db.dedicatedIp.count({ where: { nodeId: node.id } });
192	  return { imported, total };
193	}
