216	/** Find the OVH Virtual MAC currently bound to an IP, if any. */
217	async function findVirtualMacForIp(server: string, address: string): Promise<string | null> {
218	  const macs: string[] = await ovh("GET", `/dedicated/server/${server}/virtualMac`).catch(() => []);
219	  for (const m of macs) {
220	    const ips: string[] = await ovh("GET", `/dedicated/server/${server}/virtualMac/${m}/virtualAddress`).catch(() => []);
221	    if (ips.includes(address)) return m;
222	  }
223	  return null;
224	}
