226	/**
227	 * Claim a free IP for a server and set it up so the VM can use it — an OVH
228	 * Virtual MAC for an OVH-node IP, or nothing extra for a Hetzner-node IP
229	 * (Hetzner additional IPs route straight to the server's real MAC, no
230	 * separate MAC object to create). Returns the address + a MAC (OVH only,
231	 * empty string for Hetzner) + gateway, or null if none available.
232	 *
233	 * `nodeId` should be the server's OWN node — pass it explicitly from a
234	 * caller that already resolved it (e.g. worker/index.ts's `nodeFor(server)`);
235	 * omitted, this falls back to the primary node, identical to this file's
236	 * pre-multi-node behavior.
237	 */
238	export async function allocateDedicatedIp(
239	  serverId: string,
240	  vmid: number,
241	  nodeId?: string,
242	): Promise<{ address: string; virtualMac: string; gateway: string } | null> {
243	  if (SANDBOX) {
244	    // Hand out a synthetic dedicated IP without any provider call or pool mutation.
245	    return { address: sandboxIp(vmid), virtualMac: sandboxMac(vmid), gateway: "198.51.100.254" };
246	  }
247	  // Idempotent per server: PROVISION can retry (up to MAX_ATTEMPTS). If this
248	  // server already holds a fully-allocated dedicated IP, return it instead of
249	  // claiming a second pool IP — re-claiming would leak an IP and P2002 on the
250	  // unique DedicatedIp.serverId. An OVH row also needs a bound Virtual MAC to
251	  // count as "done"; a Hetzner row is done once ASSIGNED (no MAC step).
252	  const mine = await db.dedicatedIp.findUnique({ where: { serverId }, include: { node: true } });
253	  if (mine && mine.status === "ASSIGNED" && (mine.node.provider === "HETZNER" || mine.virtualMac)) {
254	    return { address: mine.address, virtualMac: mine.virtualMac ?? "", gateway: await gatewayFor(mine.node, mine.address) };
255	  }
256	
257	  const node = await resolveNode(nodeId);
258	  if (!node) return null;
259	  if (!(await dedicatedIpProviderConfigured(node.id))) return null;
260	
261	  // Atomically claim a FREE ip belonging to THIS node's pool. Excluding
262	  // purpose: INTERNAL here is a second, independent guard (alongside the
263	  // sync-time checks above) against ever handing an admin-marked internal IP
264	  // to a customer server.
265	  const claim = await db.$transaction(async (tx) => {
266	    const ip = await tx.dedicatedIp.findFirst({
267	      where: { status: "FREE", purpose: "CUSTOMER", nodeId: node.id },
268	      orderBy: { createdAt: "asc" },
269	    });
270	    if (!ip) return null;
271	    await tx.dedicatedIp.update({ where: { id: ip.id }, data: { status: "PENDING", serverId } });
272	    return ip;
273	  });
274	  if (!claim) return null;
275	
276	  try {
277	    if (node.provider === "HETZNER") {
278	      await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "ASSIGNED" } });
279	      return { address: claim.address, virtualMac: "", gateway: await gatewayFor(node, claim.address) };
280	    }
281	    // OVH branch — unchanged mechanics, just keyed off this node's own service name.
282	    const SERVER = node.providerServerId!;
283	    let mac = await findVirtualMacForIp(SERVER, claim.address);
284	    if (!mac) {
285	      // Creation is asynchronous (returns a task) — kick it off then poll.
286	      await ovhApi.createVirtualMac(SERVER, claim.address, `nxeon-${vmid}`);
287	      for (let i = 0; i < 40 && !mac; i++) {
288	        await new Promise((r) => setTimeout(r, 3000));
289	        mac = await findVirtualMacForIp(SERVER, claim.address);
290	      }
291	    }
292	    if (!mac) throw new Error("Virtual MAC not bound after creation (OVH task still pending)");
293	    await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "ASSIGNED", virtualMac: mac } });
294	    return { address: claim.address, virtualMac: mac, gateway: ovhGatewayFor(node.publicIp) };
295	  } catch (e) {
296	    // Roll the claim back to FREE on failure
297	    await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "FREE", serverId: null, virtualMac: null } });
298	    throw e;
299	  }
300	}
