302	/**
303	 * The gateway a VM should use for this IP. OVH: the well-known "/24 -> .254"
304	 * convention, same for every additional IP on that node. Hetzner: NOT a
305	 * fixed formula — Hetzner assigns a distinct gateway per single additional
306	 * IP (confirmed against Hetzner's own docs this session: additional IP
307	 * SUBNETS route via the server's main IP with no separate gateway, but
308	 * single additional IPs each come with their own gateway address) — read it
309	 * from Hetzner's own `/ip/{ip}` response rather than guessing a formula.
310	 * NOTE: the exact response field name below (`gateway`) hasn't been verified
311	 * against a real Hetzner additional IP yet (none exist in the pool at the
312	 * time this was written) — confirm it the first time this path actually
313	 * runs, before trusting it for a real customer's network config.
314	 */
315	async function gatewayFor(node: NodeRow, address: string): Promise<string> {
316	  if (node.provider === "OVH") return ovhGatewayFor(node.publicIp);
317	  try {
318	    const info = await hetznerApi.ipInfo(address);
319	    if (info?.ip?.gateway) return info.ip.gateway as string;
320	  } catch {
321	    /* fall through */
322	  }
323	  return node.publicIp; // best-effort fallback; see doc comment above
324	}
