326	/** Release a server's dedicated IP back to the pool (deletes the OVH Virtual
327	 *  MAC for an OVH-node IP; a Hetzner-node IP just gets un-assigned, no
328	 *  separate MAC object to delete). */
329	export async function releaseDedicatedIp(serverId: string): Promise<void> {
330	  if (SANDBOX) return;
331	  const ip = await db.dedicatedIp.findUnique({ where: { serverId }, include: { node: true } });
332	  if (!ip) return;
333	  if (ip.node.provider === "OVH" && ovhConfigured() && ip.virtualMac && ip.node.providerServerId) {
334	    const SERVER = ip.node.providerServerId;
335	    try {
336	      // Remove the IP from the vMAC, then delete the vMAC.
337	      await ovh("DELETE", `/dedicated/server/${SERVER}/virtualMac/${ip.virtualMac}/virtualAddress/${ip.address}`).catch(() => {});
338	      await ovh("DELETE", `/dedicated/server/${SERVER}/virtualMac/${ip.virtualMac}`).catch(() => {});
339	    } catch {
340	      /* best-effort */
341	    }
342	  }
343	  await db.dedicatedIp.update({
344	    where: { id: ip.id },
345	    data: { status: "FREE", serverId: null, virtualMac: null },
346	  });
347	  // `Server.ipAddress` is UNIQUE and separate from this pool table — every
348	  // caller used to have to remember to clear it themselves, and one (the
349	  // admin "release IP" action) didn't, which left a FREE pool row while a
350	  // live server still held that exact address in `Server.ipAddress`. The next
351	  // server to claim the pool row then failed provisioning with a P2002 on
352	  // every retry, deterministically, since the failed-provision cleanup just
353	  // re-freed the same already-stuck row. Clearing it here — for every caller,
354	  // guarded to only touch the row that still holds THIS address, since the
355	  // column also holds ordinary NAT IPs for other servers — closes that class
356	  // of bug for good instead of relying on each call site to remember.
357	  await db.server.updateMany({
358	    where: { id: serverId, ipAddress: ip.address },
359	    data: { ipAddress: null, ipv6: null },
360	  });
361	}
