363	/** Set reverse DNS (PTR) for a dedicated IP — dispatches to the owning node's provider. */
364	export async function setDedicatedReverse(address: string, reverse: string): Promise<void> {
365	  const ip = await db.dedicatedIp.findUnique({ where: { address }, include: { node: true } });
366	  if (!ip) return;
367	  if (ip.node.provider === "HETZNER") {
368	    if (!hetznerConfigured()) return;
369	    await hetznerApi.setReverse(address, reverse);
370	  } else {
371	    if (!ovhConfigured()) return;
372	    await ovhApi.setReverse(`${address}/32`, address, reverse);
373	  }
374	  await db.dedicatedIp.updateMany({ where: { address }, data: { reverse } });
375	}
