3	/**
4	 * Custom-domain DNS verification for game servers.
5	 *
6	 * Customers can point their own domain (e.g. play.mydomain.com) at their game
7	 * server by creating an A record and an SRV record on their own DNS provider.
8	 * This module checks whether those records resolve correctly.
9	 *
10	 * We never create any DNS records ourselves — the customer does it on their
11	 * provider (Cloudflare, GoDaddy, Namecheap, etc.).
12	 */
13	
14	export type DnsVerifyResult = {
15	  aOk: boolean;
16	  srvOk: boolean;
17	  /** The actual A-record value we found (if any) */
18	  aValue?: string;
19	  /** The SRV target we found */
20	  srvTarget?: string;
21	  /** The SRV port we found */
22	  srvPort?: number;
23	  /** Human-readable error detail (for unexpected failures) */
24	  aError?: string;
25	  srvError?: string;
26	};
27	
28	/**
29	 * Verify that a customer's domain has the correct DNS records for connecting
30	 * to their game server.
31	 *
32	 * @param domain     - The customer's domain, e.g. "play.mydomain.com"
33	 * @param expectedIp - The IP address the A record should point to
34	 * @param expectedPort - The port the SRV record should advertise
35	 */
36	export async function verifyCustomDomainDns(
37	  domain: string,
38	  expectedIp: string,
39	  expectedPort: number,
40	): Promise<DnsVerifyResult> {
41	  const result: DnsVerifyResult = { aOk: false, srvOk: false };
42	
43	  // --- Check A record ---
44	  try {
45	    const addresses = await dns.resolve4(domain);
46	    if (addresses.length > 0) {
47	      result.aValue = addresses[0];
48	      result.aOk = addresses.includes(expectedIp);
49	    }
50	  } catch (err: unknown) {
51	    const code = (err as NodeJS.ErrnoException).code;
52	    if (code === "ENOTFOUND" || code === "ENODATA") {
53	      result.aError = "No A record found for this domain.";
54	    } else {
55	      result.aError = `DNS lookup failed: ${code ?? "unknown error"}`;
56	    }
57	  }
58	
59	  // --- Check SRV record ---
60	  const srvName = `_minecraft._tcp.${domain}`;
61	  try {
62	    const records = await dns.resolveSrv(srvName);
63	    if (records.length > 0) {
64	      const rec = records[0];
65	      result.srvTarget = rec.name;
66	      result.srvPort = rec.port;
67	      result.srvOk = rec.port === expectedPort;
68	    }
69	  } catch (err: unknown) {
70	    const code = (err as NodeJS.ErrnoException).code;
71	    if (code === "ENOTFOUND" || code === "ENODATA") {
72	      result.srvError = "No SRV record found.";
73	    } else {
74	      result.srvError = `SRV lookup failed: ${code ?? "unknown error"}`;
75	    }
76	  }
77	
78	  return result;
79	}
