1	/**
2	 * Port-forward (DNAT) rule planning, reconciliation and PROOF.
3	 *
4	 * INCIDENT (customer-journey rehearsal 2026-07-26, finding H5): `syncPortForwards`
5	 * opened with an unconditional `iptables -t nat -F NXEON_FWD` and then rebuilt the
6	 * whole chain in a loop with no try/catch, no rollback and no read-back. `exec`
7	 * there is `promisify(execFile)`, so ONE failed `-A` rejected and aborted the
8	 * loop — every server after that point was left with no DNAT rule at all. The job
9	 * still went DONE, because DONE meant "the last `iptables -A` exited 0". The
10	 * result was a fleet-wide SSH blackhole with no notification and a dashboard
11	 * still showing everyone's port. Worse, `remove()` calls the sync AFTER deleting
12	 * the server row, so the throw re-queued DELETE, which then died on "Server not
13	 * found" and never retried the sync.
14	 *
15	 * WHAT MID-FLUSH LOOKS LIKE, and why this module does not flush:
16	 *
17	 *   A flush is an instant, total outage for every customer on the box. Everything
18	 *   between the `-F` and the last successful `-A` is a window in which live SSH
19	 *   sessions keep working (conntrack) but every NEW connection is dropped. If the
20	 *   rebuild dies halfway — a malformed IP, an ENOENT on the iptables binary, the
21	 *   worker being restarted, the DB query returning a partial fleet — the window
22	 *   never closes and nothing notices.
23	 *
24	 *   So there is no flush. We READ the chain, DIFF it against what the database
25	 *   says should be there, and apply only the difference. A rule that is already
26	 *   correct is never removed, so no failure anywhere in this module can take down
27	 *   a customer who was working before it ran. Then we read the chain BACK and
28	 *   compare it to the intent; anything missing is raised loudly with the exact
29	 *   command an operator can run. "The last iptables call exited 0" is not proof
30	 *   that the ruleset is right, and is no longer accepted as such.
31	 *
32	 * Everything here is pure except `reconcileNatChain`, which is driven through the
33	 * `NatHost` seam so test/nat-sync.test.ts can exercise it against an in-memory
34	 * fake chain with no iptables, no root and no network.
35	 */
36	
37	export type NatRule = {
38	  /** "tcp" | "udp" */
39	  proto: string;
40	  /** Public port on the host. */
41	  dport: number;
42	  /** Guest IP the packet is rewritten to. */
43	  destIp: string;
44	  /** Guest port the packet is rewritten to. */
45	  destPort: number;
46	};
47	
48	/** One server's forwarding requirements, as read from the database. */
49	export type ForwardSource = {
50	  serverId: string;
51	  hostname: string;
52	  ipAddress: string | null;
53	  sshPort: number | null;
54	  portForwards: { protocol: string; publicPort: number; guestPort: number }[];
55	};
56	
57	export type NatConflict = { proto: string; dport: number; winner: string; losers: string[] };
58	export type NatRejection = { hostname: string; reason: string };
59	
60	export type NatIntent = {
61	  /** Exactly what the chain should contain, in a stable order. */
62	  rules: NatRule[];
63	  /** Two servers claiming the same public port. The loser's rule is NOT installed. */
64	  conflicts: NatConflict[];
65	  /** Rows we refused to turn into a rule because a field was not a valid IP/port/protocol. */
66	  rejected: NatRejection[];
67	};
68	
69	const IPV4 = /^(?:(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)\.){3}(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)$/;
70	
71	function validPort(n: unknown): n is number {
72	  return typeof n === "number" && Number.isInteger(n) && n >= 1 && n <= 65535;
73	}
74	
75	/**
76	 * Turn the fleet into the exact DNAT ruleset the chain should hold.
77	 *
78	 * Two things this refuses to do quietly:
79	 *
80	 *  1. Install a rule built from a field that is not a valid IPv4 address, port or
81	 *     protocol. `execFile` with an argv array is already injection-safe, but a
82	 *     malformed value produces an iptables error mid-run, which under the old
83	 *     flush-and-rebuild is what aborted the loop and blackholed everyone after
84	 *     it. Rejected rows are reported, not silently skipped.
85	 *  2. Install two rules claiming the same protocol/public port. iptables is
86	 *     first-match, so a duplicate silently sends one customer's traffic to
87	 *     another customer's VM. The first claimant (stable order) wins and the
88	 *     collision is reported so somebody can fix the allocation.
89	 */
90	export function planNatRules(servers: readonly ForwardSource[]): NatIntent {
91	  const rules: NatRule[] = [];
92	  const conflicts: NatConflict[] = [];
93	  const rejected: NatRejection[] = [];
94	  const claimed = new Map<string, { hostname: string; index: number }>();
95	
96	  const claim = (r: NatRule, hostname: string) => {
97	    const key = `${r.proto}/${r.dport}`;
98	    const prior = claimed.get(key);
99	    if (prior) {
100	      const c = conflicts.find((x) => x.proto === r.proto && x.dport === r.dport);
101	      if (c) c.losers.push(hostname);
102	      else conflicts.push({ proto: r.proto, dport: r.dport, winner: prior.hostname, losers: [hostname] });
103	      return;
104	    }
105	    claimed.set(key, { hostname, index: rules.length });
106	    rules.push(r);
107	  };
108	
109	  // Stable order: sorted by hostname, then by public port. iptables is
110	  // first-match on distinct ports so order does not affect behaviour, but a
111	  // deterministic order makes the diff, the logs and the tests readable.
112	  const ordered = [...servers].sort((a, b) => a.hostname.localeCompare(b.hostname));
113	
114	  for (const s of ordered) {
115	    if (!s.ipAddress || !IPV4.test(s.ipAddress)) {
116	      rejected.push({ hostname: s.hostname, reason: `private IP ${JSON.stringify(s.ipAddress)} is not a valid IPv4 address` });
117	      continue;
118	    }
119	    if (!validPort(s.sshPort)) {
120	      rejected.push({ hostname: s.hostname, reason: `SSH port ${JSON.stringify(s.sshPort)} is not a valid port` });
121	    } else {
122	      claim({ proto: "tcp", dport: s.sshPort, destIp: s.ipAddress, destPort: 22 }, s.hostname);
123	    }
124	
125	    for (const f of [...s.portForwards].sort((a, b) => a.publicPort - b.publicPort)) {
126	      const proto = String(f.protocol ?? "").toLowerCase();
127	      if (proto !== "tcp" && proto !== "udp") {
128	        rejected.push({ hostname: s.hostname, reason: `port forward protocol ${JSON.stringify(f.protocol)} is not tcp or udp` });
129	        continue;
130	      }
131	      if (!validPort(f.publicPort) || !validPort(f.guestPort)) {
132	        rejected.push({
133	          hostname: s.hostname,
134	          reason: `port forward ${JSON.stringify(f.publicPort)}->${JSON.stringify(f.guestPort)} has an out-of-range port`,
135	        });
136	        continue;
137	      }
138	      claim({ proto, dport: f.publicPort, destIp: s.ipAddress, destPort: f.guestPort }, s.hostname);
139	    }
140	  }
141	
142	  return { rules, conflicts, rejected };
143	}
144	
145	/** The identity of a rule for set operations — everything that makes it distinct. */
146	export function ruleKey(r: NatRule): string {
147	  return `${r.proto}/${r.dport}->${r.destIp}:${r.destPort}`;
148	}
149	
150	/** Human-readable, and close enough to the real command to paste after `iptables -t nat -A NXEON_FWD`. */
151	export function ruleText(r: NatRule): string {
152	  return `-p ${r.proto} --dport ${r.dport} -j DNAT --to-destination ${r.destIp}:${r.destPort}`;
153	}
154	
155	/** The argv fragment shared by -A, -D and -C. */
156	export function ruleSpec(r: NatRule): string[] {
157	  return [
158	    "-p", r.proto,
159	    "--dport", String(r.dport),
160	    "-j", "DNAT",
161	    "--to-destination", `${r.destIp}:${r.destPort}`,
162	  ];
163	}
164	
165	/**
166	 * Parse `iptables -t nat -S <chain>` back into rules.
167	 *
168	 * iptables normalises what it prints (it inserts `-m tcp`, and reorders some
169	 * options), so the output is NOT byte-comparable to what we passed to `-A`. It is
170	 * parsed rather than string-matched for exactly that reason.
171	 *
172	 * Anything in our chain we cannot parse is returned in `unparsed` and never
173	 * touched. Deleting a rule we do not understand is how you turn "a stray rule
174	 * exists" into "somebody's forwarding is gone", and we do not know enough to be
175	 * making that trade silently.
176	 */
177	export function parseChainRules(chain: string, sOutput: string): { rules: NatRule[]; unparsed: string[] } {
178	  const rules: NatRule[] = [];
179	  const unparsed: string[] = [];
180	  for (const raw of String(sOutput ?? "").split("\n")) {
181	    const line = raw.trim();
182	    if (!line) continue;
183	    if (!line.startsWith(`-A ${chain} `)) continue; // -N, and jumps in other chains
184	    const body = line.slice(`-A ${chain} `.length);
185	    const proto = /(?:^|\s)-p\s+(tcp|udp)(?:\s|$)/.exec(body)?.[1];
186	    const dport = /(?:^|\s)--dport\s+(\d{1,5})(?:\s|$)/.exec(body)?.[1];
187	    const dest = /(?:^|\s)--to-destination\s+(\d{1,3}(?:\.\d{1,3}){3}):(\d{1,5})(?:\s|$)/.exec(body);
188	    const isDnat = /(?:^|\s)-j\s+DNAT(?:\s|$)/.test(body);
189	    if (!proto || !dport || !dest || !isDnat) {
190	      unparsed.push(line);
191	      continue;
192	    }
193	    const r: NatRule = { proto, dport: Number(dport), destIp: dest[1], destPort: Number(dest[2]) };
194	    if (!validPort(r.dport) || !validPort(r.destPort) || !IPV4.test(r.destIp)) {
195	      unparsed.push(line);
196	      continue;
197	    }
198	    rules.push(r);
199	  }
200	  return { rules, unparsed };
201	}
202	
203	export type NatPlan = { toAdd: NatRule[]; toDelete: NatRule[] };
204	
205	/**
206	 * What has to change to turn `actual` into `intended`.
207	 *
208	 * This is the whole point of the rewrite: a rule that is already correct appears
209	 * in neither list, so it is never removed and never re-added. There is no moment
210	 * at which a working customer's forwarding is absent from the kernel.
211	 */
212	export function natReconcilePlan(intended: readonly NatRule[], actual: readonly NatRule[]): NatPlan {
213	  const want = new Map(intended.map((r) => [ruleKey(r), r]));
214	  const have = new Map(actual.map((r) => [ruleKey(r), r]));
215	  const toAdd = [...want.entries()].filter(([k]) => !have.has(k)).map(([, r]) => r);
216	  const toDelete = [...have.entries()].filter(([k]) => !want.has(k)).map(([, r]) => r);
217	  return { toAdd, toDelete };
218	}
219	
220	export type NatVerdict = { ok: boolean; missing: NatRule[]; extra: NatRule[] };
221	
222	/**
223	 * Did the chain end up holding what we intended? Read back from the kernel, not
224	 * inferred from exit codes.
225	 */
226	export function verifyNatChain(intended: readonly NatRule[], actual: readonly NatRule[]): NatVerdict {
227	  const { toAdd: missing, toDelete: extra } = natReconcilePlan(intended, actual);
228	  return { ok: missing.length === 0 && extra.length === 0, missing, extra };
229	}
230	
231	/**
232	 * The failure sentence. Named, exported and tested because the whole defect class
233	 * is "a surface reported an outcome it did not verify" — the remedy is only worth
234	 * anything if what it says is specific enough to act on.
235	 */
236	export function natFailureMessage(opts: {
237	  chain: string;
238	  missing: readonly NatRule[];
239	  extra: readonly NatRule[];
240	  errors: readonly string[];
241	}): string {
242	  const parts: string[] = [];
243	  if (opts.missing.length) {
244	    parts.push(
245	      `${opts.missing.length} port-forward rule(s) are NOT in the ${opts.chain} chain after the sync, ` +
246	        `so that traffic is being dropped: ${opts.missing.slice(0, 8).map(ruleText).join("; ")}` +
247	        (opts.missing.length > 8 ? ` (+${opts.missing.length - 8} more)` : "")
248	    );
249	  }
250	  if (opts.extra.length) {
251	    parts.push(
252	      `${opts.extra.length} rule(s) that should have been removed are still present: ` +
253	        opts.extra.slice(0, 8).map(ruleText).join("; ")
254	    );
255	  }
256	  if (opts.errors.length) parts.push(`iptables reported: ${opts.errors.slice(0, 8).join(" | ")}`);
257	  parts.push(`Inspect the live chain with: iptables -t nat -S ${opts.chain}`);
258	  return parts.join(". ");
259	}
260	
261	// ---------------------------------------------------------------------------
262	// The seam
263	// ---------------------------------------------------------------------------
264	
265	/**
266	 * Everything `reconcileNatChain` needs from the host, as an interface rather than
267	 * a bare `execFile`.
268	 *
269	 * WHY: this function edits the live NAT table of a production box carrying paying
270	 * customers. Its decision ladder — what to delete, what to add, what counts as
271	 * proof afterwards, what to say when it does not hold — must be exercised
272	 * without touching a kernel, so the only implementation production ever uses
273	 * (`iptablesHost` in worker/network.ts) is matched by an in-memory fake in
274	 * test/nat-sync.test.ts.
275	 */
276	export type NatHost = {
277	  /** Create the chain and the PREROUTING jump if absent. Must be idempotent. */
278	  ensureChain: () => Promise<void>;
279	  /** Raw `iptables -t nat -S <chain>` output. */
280	  listChain: () => Promise<string>;
281	  addRule: (r: NatRule) => Promise<void>;
282	  deleteRule: (r: NatRule) => Promise<void>;
283	};
284	
285	export type NatSyncResult = {
286	  added: number;
287	  deleted: number;
288	  /** Rules the chain is proven to hold. */
289	  verified: number;
290	  conflicts: NatConflict[];
291	  rejected: NatRejection[];
292	  /** Lines in our chain we could not parse; left alone, reported here. */
293	  unparsed: string[];
294	};
295	
296	/**
297	 * Reconcile the chain to `intent` and PROVE the result, or throw saying exactly
298	 * what is broken.
299	 *
300	 * Failure handling is deliberately two-phase. Individual `-A`/`-D` errors are
301	 * COLLECTED rather than thrown, so one bad rule can no longer abandon every
302	 * server after it in the list — that was the H5 blackhole. Then the chain is read
303	 * back and compared to the intent, and only that comparison decides success. A
304	 * rule that failed to add but turns out to be present anyway (a concurrent sync)
305	 * is not an error; a rule that "added fine" but is not in the chain is.
306	 */
307	export async function reconcileNatChain(
308	  host: NatHost,
309	  chain: string,
310	  intent: NatIntent
311	): Promise<NatSyncResult> {
312	  await host.ensureChain();
313	
314	  const current = parseChainRules(chain, await host.listChain());
315	  const plan = natReconcilePlan(intent.rules, current.rules);
316	  const errors: string[] = [];
317	
318	  // Delete first: frees a public port that is being reassigned to another guest
319	  // in the same pass, which would otherwise be an unresolvable conflict.
320	  let deleted = 0;
321	  for (const r of plan.toDelete) {
322	    try {
323	      await host.deleteRule(r);
324	      deleted++;
325	    } catch (e: any) {
326	      errors.push(`delete ${ruleText(r)}: ${String(e?.message ?? e).slice(0, 160)}`);
327	    }
328	  }
329	
330	  let added = 0;
331	  for (const r of plan.toAdd) {
332	    try {
333	      await host.addRule(r);
334	      added++;
335	    } catch (e: any) {
336	      errors.push(`add ${ruleText(r)}: ${String(e?.message ?? e).slice(0, 160)}`);
337	    }
338	  }
339	
340	  // The proof. Not "every call exited 0" — what the kernel actually holds now.
341	  const final = parseChainRules(chain, await host.listChain());
342	  const verdict = verifyNatChain(intent.rules, final.rules);
343	  if (!verdict.ok) {
344	    throw new Error(
345	      natFailureMessage({ chain, missing: verdict.missing, extra: verdict.extra, errors })
346	    );
347	  }
348	  if (errors.length) {
349	    // Every intended rule is present and no stray remains, so forwarding is
350	    // correct — but something errored on the way and that is not nothing.
351	    console.warn(`[nat] ${chain} reconciled, but iptables errored on the way: ${errors.join(" | ")}`);
352	  }
353	
354	  return {
355	    added,
356	    deleted,
357	    verified: final.rules.length,
358	    conflicts: intent.conflicts,
359	    rejected: intent.rejected,
360	    unparsed: final.unparsed,
361	  };
362	}
