/** A single finding, before dedup + persistence. */
type Proposal = {
  category: string; // bug | feature | error | enhancement | security | performance
  severity: string; // low | medium | high | critical
  title: string; // MUST be stable across runs so dedup works (no counts/dates)
  summary: string; // one concise sentence
  detail?: string | null;
  effort?: string | null; // S | M | L
  filesHint?: string | null;
