export type DnsTargetInput = {
  status: string;
  dedicatedIp: { address: string } | null;
  portForwards: { guestPort: number; publicPort: number }[];
  nodePublicIp: string | null | undefined;
  publicIpEnv: string | undefined;
  gamePort: number;
