/**
 * Pure resolution of "what ip:port should this Minecraft server's subdomain
 * point at right now" — no I/O, fully unit-testable. Extracted out of
 * syncGameServerDns so the branching (dedicated vs. NAT-with-forward vs.
 * NAT-without-forward vs. suspended/deleting) can be tested directly.
 */
export function resolveGameServerDnsTarget(input: DnsTargetInput): { ip: string; port: number } | null {
  if (input.status === "SUSPENDED" || input.status === "DELETING") return null;
  if (input.dedicatedIp) return { ip: input.dedicatedIp.address, port: input.gamePort };
  const forward = input.portForwards.find((f) => f.guestPort === input.gamePort);
  const ip = input.nodePublicIp ?? input.publicIpEnv;
  return forward && ip ? { ip, port: forward.publicPort } : null;
}

