11	/**
12	 * Secure customer backup download.
13	 *
14	 *   GET /api/servers/[serverId]/backups/download?volid=backup:backup/vzdump-...zst
15	 *     -> streams the vzdump archive as an attachment.
16	 *
17	 * SECURITY (the whole point of the card): a customer must only ever be able to
18	 * download a backup of a server THEY own. Two independent guards:
19	 *   1. Ownership — the server row must belong to the session user (or an admin).
20	 *   2. Tenancy of the archive — the requested volid must appear in this server's
21	 *      OWN backup listing (listBackups(vmid) is filtered by the server's vmid).
22	 *      This is the identical guard requestRestore() uses, so a guessed/forged
23	 *      volid for another tenant's vmid is rejected before any disk access.
24	 * Only after both pass do we touch the filesystem, and even then the resolved
25	 * path is confined to the backup dump dir (basename only, no traversal).
26	 *
27	 * Proxmox exposes no HTTP endpoint that streams a .vma.zst archive, so the file
28	 * is read off the host filesystem (the web app runs on the Proxmox host, same as
29	 * the platform-backups status reads).
30	 */
31	export const dynamic = "force-dynamic";
32	
33	// Only ever serve real vzdump archives — never anything else in the dump dir.
34	const ARCHIVE_RE = /^vzdump-[A-Za-z0-9._-]+\.(vma|tar)(\.(zst|gz|lzo))?$/;
35	
36	export async function GET(
37	  req: NextRequest,
38	  { params }: { params: Promise<{ id: string }> }
39	) {
40	  const { id: serverId } = await params;
41	
42	  const user = await currentUser();
43	  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
44	
45	  const rl = checkRateLimit(`backups:download:${user.id}`, { max: 20, windowMs: 60_000 });
46	  if (!rl.ok) {
47	    return NextResponse.json(
48	      { error: "too many downloads — slow down", retryAfterSec: rl.retryAfterSec },
49	      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
50	    );
51	  }
52	
53	  // 1. Ownership.
54	  const server = await db.server.findUnique({
55	    where: { id: serverId },
56	    select: {
57	      id: true,
58	      userId: true,
59	      vmid: true,
60	      node: { select: { apiUrl: true, pveNode: true, tokenId: true, tokenSecret: true } },
61	    },
62	  });
63	  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) {
64	    return NextResponse.json({ error: "not found" }, { status: 404 });
65	  }
66	  if (!server.vmid) {
67	    return NextResponse.json({ error: "server has no VM yet" }, { status: 400 });
68	  }
69	
70	  const volid = req.nextUrl.searchParams.get("volid");
71	  if (!volid) return NextResponse.json({ error: "missing volid" }, { status: 400 });
72	
73	  // 2. Tenancy of the archive — must belong to THIS server's vmid, checked
74	  // against the server's OWN node (vmids collide across physical nodes).
75	  let owned: Array<{ volid: string }>;
76	  try {
77	    owned = server.node
78	      ? ((await listBackupsOn(pveForNode(server.node), server.vmid)) as Array<{ volid: string }>)
79	      : ((await listBackups(server.vmid)) as Array<{ volid: string }>);
80	  } catch {
81	    return NextResponse.json(
82	      { error: "could not verify the backup — the hypervisor is briefly unavailable" },
83	      { status: 502 }
84	    );
85	  }
86	  if (!owned.some((b) => b.volid === volid)) {
87	    return NextResponse.json({ error: "that backup was not found for this server" }, { status: 404 });
88	  }
89	
90	  // Resolve volid -> on-disk file. The basename is the only part we trust; it
91	  // must be a real vzdump archive name and cannot escape the dump dir.
92	  const filename = volid.split("/").pop() ?? "";
93	  if (!ARCHIVE_RE.test(filename)) {
94	    return NextResponse.json({ error: "unsupported backup format" }, { status: 400 });
95	  }
96	  const dumpDir = await backupDumpDir();
97	  const filePath = path.join(dumpDir, filename);
98	  if (path.dirname(path.resolve(filePath)) !== path.resolve(dumpDir)) {
99	    // Defence in depth — basename regex already forbids separators.
100	    return NextResponse.json({ error: "invalid backup path" }, { status: 400 });
101	  }
102	
103	  let size: number;
104	  try {
105	    const st = await stat(filePath);
106	    if (!st.isFile()) throw new Error("not a file");
107	    size = st.size;
108	  } catch {
109	    return NextResponse.json(
110	      { error: "backup archive is not available on the host for download" },
111	      { status: 502 }
112	    );
113	  }
114	
115	  // Stream the file rather than buffering — archives are multi-GB.
116	  const nodeStream = createReadStream(filePath);
117	  const webStream = Readable.toWeb(nodeStream) as unknown as ReadableStream<Uint8Array>;
118	
119	  return new NextResponse(webStream, {
120	    status: 200,
121	    headers: {
122	      "Content-Type": "application/octet-stream",
123	      "Content-Length": String(size),
124	      "Content-Disposition": `attachment; filename="${filename.replace(/["\\]/g, "_")}"`,
125	      "Cache-Control": "private, no-store",
126	    },
127	  });
128	}
