/**
 * Whole-system ("platform") backup visibility for /admin/backups.
 *
 * WHY THIS EXISTS
 * ---------------
 * The fleet Backups page (app/admin/backups) reads backups LIVE from Proxmox —
 * it enumerates each node's `backup` storage via /storage/backup/content. That
 * is the right source for *customer* on-demand backups, but it is structurally
 * blind to the platform's own disaster-recovery backups.
 *
 * On 2026-07-26 the whole-system backup (scripts/backup-vms.sh) was deliberately
 * moved OUT of the Proxmox `backup` storage and into a `--dumpdir`
 * (/tank/backup/platform), so that a customer clicking "Create backup" — whose
 * retention prunes by vmid inside the `backup` storage — could no longer delete
 * the platform's DR copy of that same VM. The trade-off: Proxmox only indexes
 * `<storage>/dump`, so those archives have no volid and NEVER appear in the
 * content listing the admin page reads. Result: the daily whole-system backup
 * runs and succeeds, but /admin/backups shows "no recent backup" for everything,
 * which reads as "backups are broken" when they are in fact healthy.
 *
 * This module closes that blind spot WITHOUT touching backup execution: it reads
 * the status JSON the backup units already write (/tank/backup/status/*.json) and
 * lists the dumpdir archives (/tank/backup/platform), so the panel can tell the
 * truth about the whole-system backup subsystem. Read-only; no deletion, no
 * scheduling, no Proxmox calls.
 *
 * The web app runs as the unprivileged `nxeon` user; the status files are 0644 in
 * a 0755 dir and the dumpdir is world-listable, so this read is exactly the
 * channel scripts/backup-offsite.sh documents as "the only way the portal can
 * tell the owner the truth about off-site state".
 */

import { promises as fs } from "fs";
import path from "path";

const STATUS_DIR = process.env.NXEON_BACKUP_STATUS_DIR ?? "/tank/backup/status";
const PLATFORM_DIR = process.env.NXEON_PLATFORM_BACKUP_DIR ?? "/tank/backup/platform";

/** Health of one whole-system backup subsystem (a status JSON file). */
export type SubsystemStatus = {
  key: "vm" | "host-config" | "offsite" | "verify-restore";
  label: string;
  /** null = status file missing/unreadable (we have no evidence either way). */
  ok: boolean | null;
  /** ISO timestamp of the last run, or null. */
  at: string | null;
  /** Age of the last run in ms, or null when unknown. */
  ageMs: number | null;
  /** One-line human detail (mode/dest/error/etc.), best-effort. */
  detail: string;
  /** True when the status file could not be read at all. */
  missing: boolean;
};

/** Newest platform DR archive we hold for one guest vmid. */
export type PlatformGuest = {
  vmid: number;
  count: number;
  newestAgeMs: number;
  newestFile: string;
  totalBytes: number;
};

export type PlatformBackupsView = {
  /** False when neither the status dir nor the dumpdir could be read at all. */
  available: boolean;
  statusDir: string;
  platformDir: string;
  subsystems: SubsystemStatus[];
  guests: PlatformGuest[];
  /** vmid -> newest archive age in ms, for cross-referencing the Proxmox view. */
  coverageByVmid: Record<number, number>;
  totalArchives: number;
  totalBytes: number;
};

async function readStatusFile(name: string): Promise<Record<string, unknown> | null> {
  try {
    const raw = await fs.readFile(path.join(STATUS_DIR, name), "utf8");
    return JSON.parse(raw) as Record<string, unknown>;
  } catch {
    return null;
  }
}

function ageOf(at: unknown, now: number): number | null {
  if (typeof at !== "string") return null;
  const t = Date.parse(at);
  return Number.isFinite(t) ? Math.max(0, now - t) : null;
}

