13	/**
14	 * Fetch the disk RRD series for a VM. `disk` = bytes used as seen by the
15	 * hypervisor, `maxdisk` = provisioned size. Note: for QEMU guests Proxmox
16	 * often cannot see in-guest usage, so `disk` may be 0/null — callers should
17	 * fall back to the provisioned/plan size for the "total".
18	 */
19	export async function serverDiskRrd(
20	  vmid: number,
21	  timeframe: string,
22	  conn?: NodeConn | null
23	): Promise<DiskPoint[]> {
24	  const tf = VALID_TF.includes(timeframe) ? timeframe : "day";
25	  let raw: any[];
26	  if (conn) {
27	    const client = pveFor(conn);
28	    raw = await client.get(`/nodes/${conn.pveNode}/qemu/${vmid}/rrddata`, {
29	      timeframe: tf,
30	      cf: "AVERAGE",
31	    });
32	  } else {
33	    raw = await pve.get(`/nodes/${defaultNode}/qemu/${vmid}/rrddata`, { timeframe: tf, cf: "AVERAGE" });
34	  }
35	  return (raw ?? [])
36	    .filter((r) => r && typeof r.time === "number")
37	    .map((r) => ({
38	      time: r.time,
39	      disk: typeof r.disk === "number" ? r.disk : null,
40	      maxdisk: typeof r.maxdisk === "number" ? r.maxdisk : null,
41	    }));
42	}
