12	/**
13	 * In-browser VNC console — ticket issuer.
14	 *
15	 * GET /api/console/[serverId]
16	 *
17	 * Flow:
18	 *  1. Authenticate the caller (owner or admin).
19	 *  2. Ask Proxmox for a websocket VNC proxy ticket for the server's VM
20	 *     (POST .../vncproxy?websocket=1). This returns a short-lived VNC ticket +
21	 *     an ephemeral port on the Proxmox node.
22	 *  3. Package the connection target — Proxmox API base, node, vmid, port, the
23	 *     VNC ticket, and the API token needed to authenticate the websocket
24	 *     upgrade — into an ENCRYPTED (JWE / A256GCM) token, valid 60s, with a
25	 *     unique jti so the relay can enforce single use.
26	 *  4. Return only { wsPath, ticketId } to the browser. The browser NEVER sees
27	 *     the Proxmox API token or the raw VNC ticket — those live inside the JWE,
28	 *     which only the relay (sharing AUTH_SECRET) can decrypt.
29	 *
30	 * The relay (scripts/console-proxy.mjs) receives sid=<JWE> on the browser
31	 * websocket, decrypts it, opens a TLS websocket to Proxmox with the real
32	 * credentials, and pipes bytes both ways.
33	 */
34	
35	// 256-bit symmetric key for JWE, derived from the app's AUTH_SECRET.
36	// The relay derives the identical key the same way — no extra shared secret.
37	function consoleKey(): Uint8Array {
38	  const secret = process.env.AUTH_SECRET;
39	  if (!secret) throw new Error("AUTH_SECRET is not set");
40	  return new Uint8Array(createHash("sha256").update(`nxeon-console:${secret}`).digest());
41	}
